CREATE TABLE app_users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, login text NOT NULL UNIQUE CHECK (length(login) BETWEEN 1 AND 120 AND login = lower(btrim(login))), password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, security_version bigint NOT NULL DEFAULT 1 CHECK (security_version > 0), version bigint NOT NULL DEFAULT 1 CHECK (version > 0), created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE scenario_workspaces (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE CHECK (length(btrim(code)) BETWEEN 1 AND 80), name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200), business_date date NOT NULL, operation_mode text NOT NULL DEFAULT 'LOCAL_SIMULATION' CHECK (operation_mode = 'LOCAL_SIMULATION'), initialization_state text NOT NULL DEFAULT 'NEW' CHECK (initialization_state IN ('NEW','READY')), baseline_key text, baseline_version text, version bigint NOT NULL DEFAULT 1 CHECK (version > 0), created_by bigint NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles (code text PRIMARY KEY CHECK (code IN ('INSIDE_SALES','SALES_MANAGER','OPERATIONS','FINANCE','SYSTEM_ADMIN')));
INSERT INTO roles(code) VALUES ('INSIDE_SALES'),('SALES_MANAGER'),('OPERATIONS'),('FINANCE'),('SYSTEM_ADMIN');
CREATE TABLE workspace_memberships (workspace_id bigint NOT NULL REFERENCES scenario_workspaces(id), user_id bigint NOT NULL REFERENCES app_users(id), active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1 CHECK (version > 0), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE user_roles (workspace_id bigint NOT NULL, user_id bigint NOT NULL, role_code text NOT NULL REFERENCES roles(code), active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1 CHECK (version > 0), PRIMARY KEY(workspace_id,user_id,role_code), FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_memberships(workspace_id,user_id));
CREATE TABLE legal_entities (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES scenario_workspaces(id), code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 80), name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200), base_currency text NOT NULL CHECK (base_currency IN ('EUR','USD')), active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1 CHECK (version > 0), created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(workspace_id,id), UNIQUE(workspace_id,code));
CREATE TABLE entity_memberships (workspace_id bigint NOT NULL, entity_id bigint NOT NULL, user_id bigint NOT NULL, active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1 CHECK (version > 0), PRIMARY KEY(workspace_id,entity_id,user_id), FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_memberships(workspace_id,user_id), FOREIGN KEY(workspace_id,entity_id) REFERENCES legal_entities(workspace_id,id));
CREATE TABLE setup_receipts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, receipt_key text NOT NULL UNIQUE, user_id bigint NOT NULL REFERENCES app_users(id), workspace_id bigint NOT NULL REFERENCES scenario_workspaces(id), payload_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_user_id bigint REFERENCES app_users(id), workspace_id bigint REFERENCES scenario_workspaces(id), entity_id bigint, action text NOT NULL, target_type text NOT NULL, target_id text NOT NULL, revision bigint NOT NULL, outcome text NOT NULL, detail text NOT NULL DEFAULT '', occurred_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(workspace_id,entity_id) REFERENCES legal_entities(workspace_id,id), CHECK (entity_id IS NULL OR workspace_id IS NOT NULL));
CREATE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit events are append-only'; END $$;
CREATE TRIGGER audit_events_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();
